/* Advanced SIMD in the gadget engine's AArch32 builder. The gadgets are
 * generated by engine/a32_neon.py, which documents the groups, the variant
 * index and the operand words this file packs. */
#include "translator.hpp"

#include <bit>

namespace uml::cpu::arm64::gadgets::a32::detail {

namespace {

[[nodiscard]] std::uint64_t core(int number) noexcept
{
	return static_cast<std::uint64_t>(number) * 8U;
}

} // namespace

void Translator::open_standard_fpcr()
{
	if (standard_fpcr_)
		return;
	push(G::fpcr_standard);
	standard_fpcr_ = true;
}

void Translator::close_standard_fpcr()
{
	if (!standard_fpcr_)
		return;
	push(G::fpcr_guest);
	standard_fpcr_ = false;
}

Translator::Result Translator::emit_neon(const Instruction &in,
					 const FormPlan &plan)
{
	const auto &o = in.operands;
	/* VTRN of a register with itself: the oracle swaps the words of each D
	 * register, which is VREV64 of the 32-bit lanes (the result is UNKNOWN,
	 * and the corpus records the oracle's). */
	const std::uint8_t id = (plan.sub == neon_group::vtrn && o.d == o.m &&
				 o.esize == 32) ? neon_group::vrev64 : plan.sub;
	const NeonGroup &group = kNeonGroups[id];
	/* The Q forms are named _Q only when the encoding's Q bit is the whole
	 * distinction; the operands say which it is. */
	const unsigned q = (o.regs == 2 || o.quadword_operation) ? 1U : 0U;
	unsigned sign = 0;
	unsigned alt = 0;
	switch (group.selector) {
	case NeonSelector::none:
		break;
	case NeonSelector::usign:
		sign = o.unsigned_ ? 1U : 0U;
		break;
	case NeonSelector::src_unsigned:
		sign = o.src_unsigned ? 1U : 0U;
		break;
	case NeonSelector::floating:
		alt = o.floating_point ? 1U : 0U;
		break;
	case NeonSelector::polynomial:
		alt = o.polynomial ? 1U : 0U;
		break;
	case NeonSelector::unsigned_poly:
		sign = o.unsigned_ ? 1U : 0U;
		alt = o.polynomial ? 1U : 0U;
		break;
	case NeonSelector::scalar:
		alt = o.scalar_form ? 1U : 0U;
		break;
	case NeonSelector::vcge:
		sign = o.vtype_vcge == VCGEType::unsigned_ ? 1U : 0U;
		alt = o.vtype_vcge == VCGEType::fp ? 1U : 0U;
		break;
	case NeonSelector::vcgt:
		sign = o.vtype_vcgt == VCGTtype::unsigned_ ? 1U : 0U;
		alt = o.vtype_vcgt == VCGTtype::fp ? 1U : 0U;
		break;
	case NeonSelector::ceq:
		alt = o.int_operation ? 0U : 1U;
		break;
	case NeonSelector::cvt_int:
		sign = o.unsigned_ ? 1U : 0U;
		alt = o.to_integer ? 1U : 0U;
		break;
	case NeonSelector::cvt_fixed:
		sign = o.unsigned_ ? 1U : 0U;
		alt = o.to_fixed ? 1U : 0U;
		break;
	}
	unsigned size = 0;
	if (!group.size_none && o.esize >= 8)
		size = static_cast<unsigned>(
			std::countr_zero(static_cast<unsigned>(o.esize) / 8U));

	unsigned index = 0;
	switch (group.index) {
	case NeonIndex::generic:
		index = size | q << 2 | sign << 3 | alt << 4;
		break;
	case NeonIndex::ext:
		index = static_cast<unsigned>(o.position) / 8U | q << 4;
		break;
	case NeonIndex::tbl:
		index = static_cast<unsigned>(o.length) - 1U;
		break;
	case NeonIndex::fixed:
		index = static_cast<unsigned>(o.frac_bits) - 1U | q << 5 |
			sign << 6 | alt << 7;
		break;
	case NeonIndex::qshlu: {
		static constexpr unsigned base[4] = {0, 8, 24, 56};
		index = q * 120U + base[size & 3U] +
			static_cast<unsigned>(o.shift_amount);
		break;
	}
	}
	G which = G::count;
	if (index < group.count)
		which = kNeon[group.base + index];
	if (which == G::count) {
		/* A variant the group has no gadget for: the illegal-instruction
		 * exit, which the forms test turns into a failure. */
		emit_illegal();
		return {true, false};
	}
	uses_fp_ = true;
	if (group.fp == NeonFp::all || (group.fp == NeonFp::alt && alt != 0))
		open_standard_fpcr();

	const bool by_scalar = group.scalar == NeonScalar::always ||
			       (group.scalar == NeonScalar::alt && alt != 0);
	const auto element = [&o]() noexcept {
		return d_register(o.m) + static_cast<std::uint64_t>(o.index_value) *
					       (static_cast<unsigned>(o.esize) / 8U);
	};
	push(which);
	switch (group.shape) {
	case NeonShape::dnm:
		push(d_register(o.d) | d_register(o.n) << 16 |
		     (by_scalar ? element() : d_register(o.m)) << 32);
		break;
	case NeonShape::dm:
		push(d_register(o.d) | d_register(o.m) << 16);
		break;
	case NeonShape::dmsh:
		push(d_register(o.d) | d_register(o.m) << 16);
		push(static_cast<std::uint8_t>(group.shift * o.shift_amount));
		break;
	case NeonShape::imm:
		push(d_register(o.d));
		push(o.imm64 != 0 ? o.imm64 : o.imm);
		break;
	case NeonShape::dcore:
		push(d_register(o.d) | core(o.t) << 16);
		break;
	case NeonShape::delem:
		push(d_register(o.d) | element() << 16);
		break;
	}
	return {};
}

} // namespace uml::cpu::arm64::gadgets::a32::detail
